-- V31 应急流程全景真实数据源（fm-accident-rescue 应急指挥 · 流程节点全景 / 节点处置指引）。
-- 数据来源：src/screen/lib/data/emergencyProcessData.ts（5 阶段 / 4 响应模式 / 15 流程节点）与
-- nodeGuidanceData.ts（9 条节点处置指引 + 实时值班表）；由脚本从上述 TS 常量直出，数值与文案逐一对齐。
-- 嵌套结构（动作清单 / 判据清单 / 升级规则 / 上报链路 / 岗位任务）序列化为 detail_json LONGVARCHAR，
-- 与 V27 fac_emergency_cmd.detail_json 同范式；阶段与响应模式为扁平结构，用显式列存储。
-- 列名回避保留字（start/end/status）：start_stage / end_stage / mode_code / mode_label。

CREATE TABLE fac_emergency_phase (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    phase_code VARCHAR(32) NOT NULL,
    phase_name VARCHAR(64) NOT NULL,
    start_stage INT NOT NULL,
    end_stage INT NOT NULL,
    tone VARCHAR(16) NOT NULL,
    sort_no INT NOT NULL DEFAULT 0
);

CREATE TABLE fac_emergency_response_mode (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    mode_code VARCHAR(32) NOT NULL,
    mode_label VARCHAR(64) NOT NULL,
    stage_id INT NOT NULL,
    sort_no INT NOT NULL DEFAULT 0
);

CREATE TABLE fac_emergency_process_stage (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    stage_id INT NOT NULL,
    phase_code VARCHAR(32) NOT NULL,
    detail_json LONGVARCHAR NOT NULL,
    sort_no INT NOT NULL DEFAULT 0
);

CREATE TABLE fac_emergency_node_guidance (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    node_id VARCHAR(16) NOT NULL,
    detail_json LONGVARCHAR NOT NULL,
    sort_no INT NOT NULL DEFAULT 0
);

CREATE TABLE fac_emergency_guidance_roster (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    shift_group VARCHAR(64) NOT NULL,
    supervisor VARCHAR(128) NOT NULL,
    supervisor_phone VARCHAR(32) NOT NULL,
    board_operator VARCHAR(128) NOT NULL,
    board_operator_phone VARCHAR(32) NOT NULL,
    field_operator VARCHAR(128) NOT NULL,
    field_operator_phone VARCHAR(32) NOT NULL,
    sort_no INT NOT NULL DEFAULT 0
);

