-- 15 个流程节点（previousContext/currentActions/criteriaChecklist/escalationRule 存 detail_json）
INSERT INTO fac_emergency_process_stage (stage_id, phase_code, detail_json, sort_no) VALUES (1, 'phase-team', '{"id":1,"name":"接警研判","shortName":"1. 接警研判","leadRole":"🧑 现场第一发现人 / 岗位带班","leadTitle":"巡检员 / 内操员","commandLevel":"班组处置","description":"通过巡检、仪器报警第一时间捕捉险情，按三要素（地点、介质、伤员）上报。","previousContext":["10:00:00 - 厂区 GDS 检测到气体异常","10:00:15 - 发现 T103 塔底法兰渗漏"],"currentActions":[{"id":"act-1-1","label":"按三要素向运行部调度核实报告","done":true,"type":"primary"},{"id":"act-1-2","label":"佩戴防护对现场建立初始警戒","done":true}],"criteriaChecklist":[{"id":"cri-1-1","label":"确定事故点位与介质","checked":true},{"id":"cri-1-2","label":"完成初步信息上报","checked":true}],"escalationRule":{"triggerCondition":"确认工况异常或发生真实泄漏，启动班组初始应急","fromRole":"现场第一发现人","toRole":"现场班组长","details":{"location":"加氢制氢部 T103 塔底泵 P101B 处","substance":"加氢裂化重油 / 硫化氢（H2S）","casualty":"无人员受伤","currentStatus":"现场有轻度泄漏，报警系统正常响应"}}}', 1);
INSERT INTO fac_emergency_process_stage (stage_id, phase_code, detail_json, sort_no) VALUES (2, 'phase-team', '{"id":2,"name":"一分钟应急响应与能量隔离","shortName":"2. 一分钟应急响应","leadRole":"🧑‍💼 现场班组长（岗位带班）","leadTitle":"加氢班组长","commandLevel":"班组处置","description":"一分钟内落实“该停的停、该关的关、该放的放”，执行能量隔离与物料切断。","previousContext":["10:00:30 - 已完成接警研判"],"currentActions":[{"id":"act-2-1","label":"DCS 一键急停与切断联锁","done":true,"type":"danger"},{"id":"act-2-2","label":"停运 P101B，关闭进料阀","done":true},{"id":"act-2-3","label":"开启紧急泄压阀门降压","done":true}],"criteriaChecklist":[{"id":"cri-2-1","label":"能量隔离阀关毕率 100%","checked":true},{"id":"cri-2-2","label":"无关人员撤至上风向","checked":true}],"escalationRule":{"triggerCondition":"一分钟能量隔离完成，申请运行部级预案评定","fromRole":"现场班组长","toRole":"运行部区域主管","details":{"location":"T103 塔及泵房区域","substance":"加氢裂化重油","casualty":"0人受伤","currentStatus":"进料切断完成，塔压下降中"}}}', 2);
INSERT INTO fac_emergency_process_stage (stage_id, phase_code, detail_json, sort_no) VALUES (3, 'phase-team', '{"id":3,"name":"三分钟退守稳态","shortName":"3. 三分钟退守稳态","leadRole":"🧑‍💻 运行部区域主管","leadTitle":"加氢运行部主管","commandLevel":"班组处置","description":"三分钟内完成工艺退守稳态：降温降压、物料导空、系统隔离。","previousContext":["10:01:00 - 能量隔离完成"],"currentActions":[{"id":"act-3-1","label":"降温降压退守稳态","done":true},{"id":"act-3-2","label":"物料导空并完成系统隔离","done":false,"type":"warning"},{"id":"act-3-3","label":"评估是否达到升级条件","done":false,"type":"primary"}],"criteriaChecklist":[{"id":"cri-3-1","label":"塔体压力降至安全阈值","checked":true},{"id":"cri-3-2","label":"泄漏点气体浓度受控","checked":false}],"escalationRule":{"triggerCondition":"退守稳态期间泄漏扩大或浓度超限，升级至运行部级预案","fromRole":"运行部区域主管","toRole":"运行部级应急指挥部","details":{"location":"加氢裂化装置区","substance":"加氢裂化重油 / 硫化氢","casualty":"0人受伤","currentStatus":"塔压下降中，仍有少量介质渗出"}}}', 3);
INSERT INTO fac_emergency_process_stage (stage_id, phase_code, detail_json, sort_no) VALUES (4, 'phase-team', '{"id":4,"name":"五分钟消气防联动","shortName":"4. 五分钟消气防联动","leadRole":"🚒 消气防救援力量","leadTitle":"消气防指挥","commandLevel":"班组处置","description":"五分钟内消气防联动：水幕隔离、泄漏稀释、人员清点，防止气体扩散形成闪爆。","previousContext":["10:02:00 - 申请消气防联动"],"currentActions":[{"id":"act-4-1","label":"启动水幕隔离与泄漏稀释","done":false,"type":"danger"},{"id":"act-4-2","label":"气体浓度连续监测与警戒","done":false},{"id":"act-4-3","label":"全装置人员清点确认","done":false}],"criteriaChecklist":[{"id":"cri-4-1","label":"下风向 100m 内无人员","checked":false},{"id":"cri-4-2","label":"气体浓度不再上升","checked":false}],"escalationRule":{"triggerCondition":"班组处置无法控制，需升级至运行部级应急","fromRole":"消气防指挥","toRole":"运行部级应急指挥部","details":{"location":"加氢裂化装置区及周边","substance":"加氢裂化重油 / 硫化氢","casualty":"0人受伤","currentStatus":"水幕已启动，浓度持续监测中"}}}', 4);
