INSERT INTO fac_emergency_process_stage (stage_id, phase_code, detail_json, sort_no) VALUES (14, 'phase-close', '{"id":14,"name":"应急终止","shortName":"14. 应急终止","leadRole":"✅ 现场处置组","leadTitle":"现场指挥","commandLevel":"收尾阶段","description":"确认泄漏点封堵、气体浓度达标、污染水全部回收，解除现场警戒。","previousContext":["当前级别处置完成，进入收尾"],"currentActions":[{"id":"act-14-1","label":"泄漏点封堵确认","done":false},{"id":"act-14-2","label":"现场气体浓度复测达标","done":false},{"id":"act-14-3","label":"解除警戒与恢复通行","done":false}],"criteriaChecklist":[{"id":"cri-14-1","label":"泄漏源彻底消除","checked":false},{"id":"cri-14-2","label":"无二次衍生隐患","checked":false}],"escalationRule":{"triggerCondition":"处置完成确认后转入总结评估","fromRole":"现场指挥","toRole":"总结评估组","details":{"location":"T103 塔区域","substance":"-","casualty":"0人受伤","currentStatus":"现场处置完成"}}}', 14);
INSERT INTO fac_emergency_process_stage (stage_id, phase_code, detail_json, sort_no) VALUES (15, 'phase-close', '{"id":15,"name":"总结评估与恢复","shortName":"15. 总结评估与恢复","leadRole":"📋 总结评估组","leadTitle":"应急办主任","commandLevel":"收尾阶段","description":"事故原因调查、损害评估、环境跟踪，确认恢复生产条件并归档复盘。","previousContext":["10:40:00 - 应急终止完成"],"currentActions":[{"id":"act-15-1","label":"事故原因调查组成立","done":false},{"id":"act-15-2","label":"设备损害评估与修复计划","done":false},{"id":"act-15-3","label":"恢复生产条件确认","done":false}],"criteriaChecklist":[{"id":"cri-15-1","label":"调查报告完成","checked":false},{"id":"cri-15-2","label":"生产恢复条件具备","checked":false}],"escalationRule":{"triggerCondition":"总结归档完成，应急流程关闭","fromRole":"总结评估组","toRole":"公司应急指挥中心","details":{"location":"茂名石化厂区","substance":"-","casualty":"0人受伤","currentStatus":"总结与恢复进行中"}}}', 15);

